let input=$input.first().json; if(input.payload) input=typeof input.payload==='string'?JSON.parse(input.payload):input.payload; if(input.body) input=input.body;
const required=['projectId','incidentId','fixRequestId','repository','prNumber','buildNumber','jenkinsJob','jenkinsStatus']; const missing=required.filter(k=>input[k]===undefined||input[k]===null||input[k]===''); if(missing.length) throw new Error('INVALID_VALIDATION_CONTRACT:'+missing.join(','));
const repository=String(input.repository).replace(/^https?:\/\/github\.com\//,'').replace(/\.git$/,'').toLowerCase(); if(repository.split('/').length!==2) throw new Error('INVALID_REPOSITORY');
return [{json:{projectId:String(input.projectId),incidentId:String(input.incidentId),fixRequestId:String(input.fixRequestId),repository,prNumber:Number(input.prNumber),prUrl:String(input.prUrl||''),buildNumber:Number(input.buildNumber),buildUrl:String(input.buildUrl||''),jenkinsJob:String(input.jenkinsJob),jenkinsStatus:String(input.jenkinsStatus).toUpperCase(),analysisId:input.analysisId?String(input.analysisId):null,requiredStages:Array.isArray(input.requiredStages)?input.requiredStages:[],unresolvedBlockingCount:Number(input.unresolvedBlockingCount||0)}}];

const ctx=$('Extract Validation Context').first().json; let incident=null; try{incident=$('Get Incident From DB').first().json}catch{}; let sonar={};try{sonar=$('Get SonarQube PR Quality Gate').first().json||{}}catch{};
const sonarCorrelationVerified=!!ctx.analysisId&&!!sonar.projectStatus; const sonarStatus=sonarCorrelationVerified?String(sonar.projectStatus.status||'UNAVAILABLE').toUpperCase():'CORRELATION_PENDING'; const jenkinsStatus=ctx.jenkinsStatus; const requiredFailures=ctx.requiredStages.filter(s=>s.required!==false&&s.status!=='PASSED'&&!(s.status==='WARNING'&&!s.blocking));
const correlationVerified=!!incident?.id&&incident.id===ctx.incidentId&&Number(ctx.buildNumber)>Number(incident.buildNumber||0)&&sonarCorrelationVerified; const passed=jenkinsStatus==='SUCCESS'&&sonarStatus==='OK'&&correlationVerified&&requiredFailures.length===0&&ctx.unresolvedBlockingCount===0;
return [{json:{...ctx,validationStatus:passed?'VALIDATED':'FAILED',passed,sonarStatus,sonarCorrelationVerified,correlationVerified,requiredStagesStatus:requiredFailures.length?'FAILED':'PASSED',failureReasons:[jenkinsStatus!=='SUCCESS'?'Jenkins='+jenkinsStatus:null,sonarStatus!=='OK'?'Sonar='+sonarStatus:null,!correlationVerified?'Correlation unverified':null,...requiredFailures.map(s=>s.stage+'='+s.status),ctx.unresolvedBlockingCount?ctx.unresolvedBlockingCount+' unresolved blockers':null].filter(Boolean),timestamp:new Date().toISOString()}}];
